/*
 * A API do chat: os recursos JSON:API `chat-channels`, `chat-messages` e
 * `chat-threads` (extend/chat.php), com as ações deles, a busca de pessoas
 * (`/users/canela-chat-search`) e o envio de imagens (`/chat/uploads`).
 *
 * O chat continua trabalhando com objetos simples (types.ts), e não com
 * modelos do store: ele muda o tempo todo (mensagens, reações, contagens) e o
 * front mexe neles direto a cada evento. Por isso cada chamada daqui devolve
 * o documento já como esses objetos — o id e os atributos lado a lado —, e
 * os usuários do `included` vão para o store do Flarum (Avatar, nome,
 * perfil), como antes.
 *
 * Os parâmetros da URL vão em `filter[…]` e `page[…]`: o servidor JSON:API
 * recusa os nomes soltos (`?q=`).
 */
import app from 'flarum/forum/app';
const CHANNELS = 'chat-channels';
const MESSAGES = 'chat-messages';
const THREADS = 'chat-threads';

/** Sem alerta de erro: para as chamadas de fundo (estado, polling, "lido"). */
export const quiet = {
  errorHandler: () => {}
};
function apiBase() {
  return (app.forum.attribute('apiUrl') || '/api').replace(/\/+$/, '');
}
function clean(params) {
  if (!params) return undefined;
  const out = {};
  Object.entries(params).forEach(([key, value]) => {
    if (value === undefined || value === null || value === '') return;
    if (typeof value === 'object' && !Array.isArray(value)) {
      const nested = clean(value);
      if (nested && Object.keys(nested).length) out[key] = nested;
    } else {
      out[key] = value;
    }
  });
  return out;
}
async function request(method, path, body, params, options = {}) {
  const result = await app.request({
    method,
    url: apiBase() + path,
    body: body,
    params: clean(params),
    ...(body instanceof FormData ? {
      serialize: raw => raw
    } : {}),
    ...options
  });
  if (result && typeof result === 'object' && 'data' in result) absorbUsers(result);
  return result;
}

/** Os usuários do documento (no `data` ou no `included`) vão para o store. */
function absorbUsers(doc) {
  const primary = Array.isArray(doc.data) ? doc.data : doc.data ? [doc.data] : [];
  [...primary, ...(doc.included || [])].filter(resource => resource.type === 'users').forEach(resource => app.store.pushObject(resource));
}

/** O recurso como objeto simples; o `channelType` (o `type` é reservado no JSON:API) volta a ser o `type` do canal. */
function plain(resource) {
  const item = {
    id: Number(resource.id),
    ...(resource.attributes || {})
  };
  if ('channelType' in item) {
    item.type = item.channelType;
    delete item.channelType;
  }
  return item;
}
function list(doc) {
  return Array.isArray(doc.data) ? doc.data : doc.data ? [doc.data] : [];
}
function included(doc, type) {
  return (doc.included || []).filter(resource => resource.type === type).map(resource => plain(resource));
}
function thread(doc, resource) {
  const item = plain(resource);
  const original = resource.relationships?.originalMessage?.data;
  const message = original ? (doc.included || []).find(r => r.type === MESSAGES && r.id === original.id) : null;
  item.originalMessage = message ? plain(message) : null;
  return item;
}
function write(type, attributes, relationships) {
  return {
    data: {
      type,
      attributes,
      ...(relationships ? {
        relationships
      } : {})
    }
  };
}
const one = doc => plain(list(doc)[0]);
const many = doc => list(doc).map(resource => plain(resource));

// ─── Canais ─────────────────────────────────────────────────────────────────

export async function state(options = {}) {
  return {
    channels: many(await request('GET', `/${CHANNELS}/state`, undefined, undefined, options))
  };
}
export async function browse(filter, offset = 0) {
  const doc = await request('GET', `/${CHANNELS}`, undefined, {
    filter,
    page: {
      offset: offset || undefined
    }
  });
  return {
    channels: many(doc),
    hasMore: !!doc.links?.next
  };
}
export async function channel(id, options = {}) {
  return {
    channel: one(await request('GET', `/${CHANNELS}/${id}`, undefined, undefined, options))
  };
}
export async function createChannel(attributes) {
  return {
    channel: one(await request('POST', `/${CHANNELS}`, write(CHANNELS, attributes)))
  };
}
export async function updateChannel(id, attributes) {
  return {
    channel: one(await request('PATCH', `/${CHANNELS}/${id}`, write(CHANNELS, attributes)))
  };
}
export async function deleteChannel(id) {
  await request('DELETE', `/${CHANNELS}/${id}`);
}

/** Abre (ou reabre) a MD com essas pessoas; com `name`, um chat em grupo novo. */
export async function openDirect(userIds, name) {
  return {
    channel: one(await request('POST', `/${CHANNELS}/direct`, {
      userIds,
      name: name || undefined
    }))
  };
}
export async function follow(id) {
  return {
    channel: one(await request('POST', `/${CHANNELS}/${id}/membership`))
  };
}
export async function updateMembership(id, attributes) {
  return {
    channel: one(await request('PATCH', `/${CHANNELS}/${id}/membership`, attributes))
  };
}

/** Sair do canal; de um grupo de MD, o canal some (e a resposta vem vazia). */
export async function leave(id) {
  const doc = await request('DELETE', `/${CHANNELS}/${id}/membership`);
  return {
    channel: doc?.data ? one(doc) : null
  };
}
export async function members(id, q, offset = 0) {
  const doc = await request('GET', `/${CHANNELS}/${id}/members`, undefined, {
    filter: {
      q
    },
    page: {
      offset: offset || undefined
    }
  });
  return {
    memberIds: list(doc).map(user => Number(user.id)),
    hasMore: !!doc.meta?.hasMore,
    total: Number(doc.meta?.total || 0)
  };
}
export async function addMembers(id, userIds) {
  return {
    channel: one(await request('POST', `/${CHANNELS}/${id}/members`, {
      userIds
    }))
  };
}
export async function markRead(id, messageId, options = {}) {
  return {
    channel: one(await request('POST', `/${CHANNELS}/${id}/read`, {
      messageId
    }, undefined, options))
  };
}
export async function typing(id, isTyping, threadId) {
  await request('POST', `/${CHANNELS}/${id}/typing`, {
    typing: isTyping,
    threadId
  }, undefined, quiet);
}
export async function pins(id, options = {}) {
  return {
    messages: many(await request('GET', `/${CHANNELS}/${id}/pins`, undefined, undefined, options))
  };
}
export async function pinsRead(id) {
  await request('POST', `/${CHANNELS}/${id}/pins-read`, undefined, undefined, quiet);
}

/** O polling sem websocket: as novas, as que mudaram, as que sumiram e quem está digitando. */
export async function updates(id, filter) {
  const doc = await request('GET', `/${CHANNELS}/${id}/updates`, undefined, {
    filter
  }, quiet);
  const all = many(doc);
  const fresh = new Set(doc.meta?.newIds || []);
  return {
    messages: all.filter(message => fresh.has(message.id)),
    changed: all.filter(message => !fresh.has(message.id)),
    removedIds: doc.meta?.removedIds || [],
    typingUserIds: doc.meta?.typingUserIds || [],
    now: doc.meta?.now
  };
}

// ─── Mensagens ──────────────────────────────────────────────────────────────

/** Uma página de mensagens por cursor (`around`, `before` ou `after`). */
export async function messages(channelId, page, threadId) {
  const doc = await request('GET', `/${MESSAGES}`, undefined, {
    filter: {
      channel: channelId,
      thread: threadId || undefined
    },
    page
  });
  return {
    messages: many(doc),
    meta: doc.meta
  };
}
export async function sendMessage(channelId, attributes, options = {}) {
  const body = write(MESSAGES, attributes, {
    channel: {
      data: {
        type: CHANNELS,
        id: String(channelId)
      }
    }
  });
  return {
    message: one(await request('POST', `/${MESSAGES}`, body, undefined, options))
  };
}
export async function message(id, options = {}) {
  return {
    message: one(await request('GET', `/${MESSAGES}/${id}`, undefined, undefined, options))
  };
}
export async function updateMessage(id, attributes) {
  return {
    message: one(await request('PATCH', `/${MESSAGES}/${id}`, write(MESSAGES, attributes)))
  };
}

/** Apagar é brando: a resposta é a mensagem como ficou (recolhida para o autor e a moderação). */
export async function deleteMessage(id) {
  return {
    message: one(await request('DELETE', `/${MESSAGES}/${id}`))
  };
}
export async function restoreMessage(id) {
  return {
    message: one(await request('POST', `/${MESSAGES}/${id}/restore`))
  };
}
export async function react(id, emoji, action) {
  return {
    message: one(await request('POST', `/${MESSAGES}/${id}/reactions`, {
      emoji,
      action
    }))
  };
}
export async function pin(id, value) {
  return {
    message: one(await request(value ? 'POST' : 'DELETE', `/${MESSAGES}/${id}/pin`))
  };
}

/** "Pesquisar no chat": os resultados e os canais deles. */
export async function search(q, sort, channelId) {
  const doc = await request('GET', `/${MESSAGES}/search`, undefined, {
    filter: {
      q,
      channel: channelId
    },
    sort: sort === 'latest' ? '-createdAt' : undefined
  });
  return {
    results: many(doc),
    channels: included(doc, CHANNELS)
  };
}

// ─── Fios ───────────────────────────────────────────────────────────────────

/** Os fios de um canal, ou — sem canal — os que o leitor acompanha, com os canais deles. */
export async function threads(channelId) {
  const doc = await request('GET', `/${THREADS}`, undefined, {
    filter: {
      channel: channelId
    }
  });
  return {
    threads: list(doc).map(resource => thread(doc, resource)),
    channels: included(doc, CHANNELS)
  };
}
export async function fetchThread(id) {
  const doc = await request('GET', `/${THREADS}/${id}`);
  return {
    thread: thread(doc, list(doc)[0])
  };
}
export async function updateThread(id, attributes) {
  const doc = await request('PATCH', `/${THREADS}/${id}`, write(THREADS, attributes));
  return {
    thread: thread(doc, list(doc)[0])
  };
}
export async function markThreadRead(id, messageId, options = {}) {
  const doc = await request('POST', `/${THREADS}/${id}/read`, {
    messageId
  }, undefined, options);
  return {
    thread: thread(doc, list(doc)[0])
  };
}

// ─── Pessoas e imagens ──────────────────────────────────────────────────────

/** A busca de pessoas do chat (o `@` e "Nova mensagem"); com o canal, quem é membro. */
export async function users(q, channelId) {
  const doc = await request('GET', '/users/canela-chat-search', undefined, {
    filter: {
      q,
      channel: channelId
    }
  }, quiet);
  return {
    userIds: list(doc).map(user => Number(user.id)),
    memberIds: doc.meta?.memberIds || []
  };
}

/** Envia uma imagem do composer (multipart): ela fica solta até a mensagem sair. */
export async function upload(file) {
  const body = new FormData();
  body.append('file', file);
  return request('POST', '/chat/uploads', body);
}
flarum.reg.add('ramon-canela', 'forum/features/chat/api', { quiet: quiet, });